import argparse, subprocess, sys, datetime, base64
from pathlib import Path

FILES = {
    'tools/ps1/register_pack_fetcher.ps1': b'',
    'tools/ps1/install_startup_loop.ps1': b'',
    'docs/phone_workflow.md': b'',
}

def run(a, cwd=None, check=True): subprocess.run(a, cwd=cwd, check=check)

def find_root(seed: Path) -> Path:
    p = seed
    for _ in range(8):
        if (p/'.git').exists(): return p
        p = p.parent
    return seed

def main():
    here = Path(__file__).resolve()
    root = find_root(here)
    for rel, b64 in FILES.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))

    step='PA-314'; branch=f'step/{step}-nonadmin-scheduling'
    ts=datetime.datetime.now().strftime('%Y%m%d_%H%M')
    run(['git','checkout','-B',branch], root)
    run(['git','add','-A'], root)
    run(['git','commit','-m', f'{step}: non-admin scheduler + Startup loop + phone doc'], root, check=False)
    run(['git','push','-u','origin',branch], root, check=False)
    print(f'{step} done.')

if __name__ == '__main__': sys.exit(main())